'use strict';

// MODULES //

var EventEmitter = require( 'events' ).EventEmitter;
var tape = require( 'tape' );
var instanceOf = require( '@stdlib/assert/instance-of' );
var Scale = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Scale, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function is a constructor', function test( t ) {
	var scale = new Scale({
		'name': 'xScale'
	});
	t.strictEqual( instanceOf( scale, Scale ), true, 'returns expected value' );
	t.end();
});

tape( 'the constructor does not require the `new` keyword', function test( t ) {
	var scale;
	var fcn;

	fcn = Scale;
	scale = fcn({
		'name': 'xScale'
	});
	t.strictEqual( instanceOf( scale, Scale ), true, 'returns expected value' );
	t.end();
});

tape( 'the constructor does not require the `new` keyword (options)', function test( t ) {
	var scale;
	var fcn;

	fcn = Scale;
	scale = fcn({
		'name': 'xScale',
		'type': 'log'
	});
	t.strictEqual( instanceOf( scale, Scale ), true, 'returns expected value' );
	t.strictEqual( scale.type, 'log', 'returns expected value' );
	t.end();
});

tape( 'the constructor throws an error if provided an options argument which is not an object', function test( t ) {
	var values;
	var i;

	values = [
		'5',
		5,
		NaN,
		null,
		void 0,
		true,
		false,
		[],
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			var scale = new Scale( value ); // eslint-disable-line no-unused-vars
		};
	}
});

tape( 'the constructor throws an error if not provided a `name` option', function test( t ) {
	t.throws( foo, TypeError, 'throws an error' );
	t.end();

	function foo() {
		var scale = new Scale( {} ); // eslint-disable-line no-unused-vars
	}
});

