tape( 'the constructor has a read-only `name` property', function test( t ) {
	t.strictEqual( Scale.name, 'Scale', 'returns expected value' );
	t.throws( foo, TypeError, 'throws an error' );
	t.end();

	function foo() {
		Scale.name = 'beep';
	}
});

tape( 'the constructor returns an instance having a `toJSON` method for serializing an instance to JSON', function test( t ) {
	var expected;
	var scale;
	var json;

	scale = new Scale({
		'name': 'xScale'
	});
	json = scale.toJSON();

	expected = {
		'name': 'xScale',
		'reverse': false,
		'round': false,
		'type': 'linear'
	};
	t.deepEqual( json, expected, 'returns expected value' );
	t.end();
});

tape( 'the constructor returns an instance having a `toJSON` method for serializing an instance to JSON (options)', function test( t ) {
	var expected;
	var scale;
	var json;

	scale = new Scale({
		'name': 'xScale',
		'type': 'log',
		'round': true,
		'reverse': true
	});
	json = scale.toJSON();

	expected = {
		'name': 'xScale',
		'reverse': true,
		'round': true,
		'type': 'log'
	};
	t.deepEqual( json, expected, 'returns expected value' );
	t.end();
});

tape( 'the `toJSON` method is implicitly invoked by `JSON.stringify`', function test( t ) {
	var expected;
	var scale;

	scale = new Scale({
		'name': 'xScale'
	});

	expected = {
		'name': 'xScale',
		'reverse': false,
		'round': false,
		'type': 'linear'
	};
	t.strictEqual( JSON.stringify( scale ), JSON.stringify( expected ), 'returns expected value' );
	t.end();
});

tape( 'the constructor returns an instance which is an EventEmitter', function test( t ) {
	var scale = new Scale({
		'name': 'xScale'
	});
	t.strictEqual( instanceOf( scale, EventEmitter ), true, 'returns expected value' );
	t.end();
});

tape( 'the constructor ignores unrecognized options', function test( t ) {
	var scale;

	scale = new Scale({
		'name': 'xScale',
		'beep': 'boop',
		'foo': 'bar'
	});

	t.strictEqual( scale.name, 'xScale', 'returns expected value' );
	t.strictEqual( scale.beep, void 0, 'returns expected value' );
	t.strictEqual( scale.foo, void 0, 'returns expected value' );

	t.end();
});
